-- session_id stays the (global) integer primary key: it is generated by the database, so it never collides
-- across tenants. Every query also filters by tenant_id.
CREATE TABLE api_sessions_new (
    session_id INTEGER PRIMARY KEY NOT NULL,
    tenant_id TEXT NOT NULL DEFAULT 'default',
    expires_at DATETIME NOT NULL,
    username TEXT NOT NULL,
    last_access_at DATETIME NOT NULL,
    user_agent TEXT,
    ip_address TEXT
);
INSERT INTO api_sessions_new (session_id, tenant_id, expires_at, username, last_access_at, user_agent, ip_address)
    SELECT session_id, 'default', expires_at, username, last_access_at, user_agent, ip_address FROM api_sessions;
DROP INDEX IF EXISTS idx_expires_at_time;
DROP INDEX IF EXISTS idx_username;
DROP TABLE api_sessions;
ALTER TABLE api_sessions_new RENAME TO api_sessions;

CREATE INDEX idx_expires_at_time
	ON api_sessions (DATETIME(expires_at) DESC);

-- username may not be unique as the user may create new tokens before old ones are deleted/expired
CREATE INDEX idx_tenant_username
  ON api_sessions (tenant_id, username);
